func sameValue(a, b any) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	if ai, ok := toInt64(a); ok {
		bi, ok2 := toInt64(b)
		return ok2 && ai == bi
	}
	return a == b
}

// coercible memakai pengonversi nilai evaluator (sumber kebenaran paritas Go dan TypeScript): nilai sah bila
// pengujian isnull tidak menghasilkan alasan tak tentu.
func coercible(ft metadata.FieldType, raw any) bool {
	res := metadata.IsNull("v", false).Eval(metadata.Types{"v": ft}, metadata.Record{"v": raw})
	return len(res.Reasons) == 0
}

func toInt64(v any) (int64, bool) {
	switch x := v.(type) {
	case int:
		return int64(x), true
	case int8:
		return int64(x), true
	case int16:
		return int64(x), true
	case int32:
		return int64(x), true
	case int64:
		return x, true
	case uint8:
		return int64(x), true
	case uint16:
		return int64(x), true
	case uint32:
		return int64(x), true
	case json.Number:
		n, err := x.Int64()
		return n, err == nil
	}
	return 0, false
}

// checkValue memeriksa satu nilai non-null; mengembalikan kode galat ("" bila sah).
func checkValue(f *FieldSpec, v any) string {
	switch f.Type {
	case metadata.TypeString, metadata.TypeText:
		s, ok := v.(string)
		if !ok {
			return CodeInvalidType
		}
		return checkText(f, s)
	case metadata.TypeEnum:
		s, ok := v.(string)
		if !ok {
			return CodeInvalidType
		}
		for _, e := range f.Enum {
			if e == s {
				return ""
			}
		}
		return CodeInvalidEnumValue
	case metadata.TypeBoolean:
		if _, ok := v.(bool); !ok {
			return CodeInvalidType
		}
	case metadata.TypeUUID:
		if _, ok := v.(string); !ok {
			return CodeInvalidType
		}
		if !coercible(f.Type, v) {
			return CodeInvalidUUID
		}
	case metadata.TypeDate:
		if _, ok := v.(string); !ok {
			return CodeInvalidType
		}
		if !coercible(f.Type, v) {
			return CodeInvalidDate
		}
	case metadata.TypeDateTime:
		if _, ok := v.(string); !ok {
			return CodeInvalidType
		}
		if !coercible(f.Type, v) {
			return CodeInvalidDateTime
		}
	case metadata.TypeInteger:
		n, ok := toInt64(v)
		if !ok {
			return CodeInvalidType
		}
		if !coercible(f.Type, n) {
			return CodeInvalidType
		}
		return checkRange(f, metadata.DecimalFromInt(n))
	case metadata.TypeDecimal:
		s, ok := v.(string)
		if !ok {
			return CodeInvalidType // desimal selalu string, tidak pernah angka JSON
		}
		d, ok := metadata.ParseDecimal(s)
		if !ok {
			return CodeInvalidDecimal
		}
		if code := checkDecimalShape(f, s); code != "" {
			return code
		}
		return checkRange(f, d)
	}
	return ""
}

func checkText(f *FieldSpec, s string) string {
	if strings.ContainsRune(s, 0) || !utf8.ValidString(s) {
		return CodeInvalidCharacters // PostgreSQL menolak NUL; UTF-8 tidak sah bukan teks
	}
	n := utf8.RuneCountInString(s)
	if f.MinLength > 0 && n < f.MinLength {
		return CodeTooShort
	}
	if f.MaxLength > 0 && n > f.MaxLength {
		return CodeTooLong
	}
	if f.Pattern != "" {
		if !matchPattern(f.Pattern, s) {
			return CodePatternMismatch
		}
	}
	switch f.Format {
	case "email":
		if n > maxEmailLen || !emailRe.MatchString(s) {
			return CodeInvalidFormat
		}
	case "url":
		if !isHTTPURL(s) {
			return CodeInvalidFormat
		}
	}
	return ""
}

var emailRe = regexp.MustCompile(`^[^@\s]+@[^@\s]+\.[^@\s]+$`)

// isHTTPURL hanya memvalidasi skema http atau https dan adanya host; URL tidak pernah diambil server (SSRF).
func isHTTPURL(s string) bool {
	u, err := url.Parse(s)
	if err != nil || u.Host == "" {
		return false
	}
	return u.Scheme == "http" || u.Scheme == "https"
}

var patternCache sync.Map // string -> *metadata.Pattern (nil bila pola tidak sah)

// matchPattern mencocokkan pola subset RE2 yang divalidasi sdk/metadata (waktu linear). Pola yang tidak lolos
// validator dianggap tidak cocok (gagal tertutup).
func matchPattern(pattern, s string) bool {
	if c, ok := patternCache.Load(pattern); ok {
		p, _ := c.(*metadata.Pattern)
		return p != nil && p.Match(s)
	}
	p, err := metadata.CompilePattern(pattern)
	if err != nil {
		p = nil
	}
	patternCache.Store(pattern, p)
	return p != nil && p.Match(s)
}

// checkDecimalShape menegakkan numeric(p,s): digit pecahan (tanpa nol di belakang) paling banyak Scale dan
// digit bulat paling banyak Precision-Scale. Tanpa Precision dan Scale tidak ada batas bentuk.
func checkDecimalShape(f *FieldSpec, s string) string {
	if f.Precision == 0 && f.Scale == 0 {
		return ""
	}
	s = strings.TrimPrefix(s, "-")
	intPart, frac, _ := strings.Cut(s, ".")
	frac = strings.TrimRight(frac, "0")
	if len(frac) > f.Scale {
		return CodeDecimalScaleExceeded
	}
	if intPart == "0" {
		intPart = ""
	}
	if len(intPart) > f.Precision-f.Scale {
		return CodeDecimalPrecisionExceeds
	}
	return ""
}

func checkRange(f *FieldSpec, d metadata.Decimal) string {
	if f.Minimum != "" {
		if lo, ok := metadata.ParseDecimal(f.Minimum); ok && d.Cmp(lo) < 0 {
			return CodeBelowMinimum
		}
	}
	if f.Maximum != "" {
		if hi, ok := metadata.ParseDecimal(f.Maximum); ok && d.Cmp(hi) > 0 {
			return CodeAboveMaximum
		}
	}
	return ""
}

// Axis mengembalikan sumbu status tambahan menurut nama field.
func (s *ResourceSpec) Axis(field string) (*StatusSpec, bool) {
	for i := range s.Axes {
		if s.Axes[i].Field == field {
			return &s.Axes[i], true
		}
	}
	return nil, false
}

// RenamePairs mengembalikan pasangan rename (nama baru, nama lama) dari field `migrateFrom`. Selama masa transisi
// (Requirement 12.3) kedua bentuk diterima dan diisi; otorisasi field (CheckWrite dan MaskFields) dihitung atas
// field kanonik, yaitu nama baru, dan keduanya berklasifikasi dan berkelompok sama (Requirement 12.6).
func (s *ResourceSpec) RenamePairs() [][2]string {
	var out [][2]string
	for i := range s.Fields {
		if f := &s.Fields[i]; f.MigrateFrom != "" {
			out = append(out, [2]string{f.Name, f.MigrateFrom})
		}
	}
	return out
}
